-- Build a source list: price in copper, limited = set of npcIDs with limited stock.
local function S(price, ids, limitedSet)
  local t = {}
  for _, id in ipairs(ids) do
    local v = V[id]
    t[#t + 1] = { npc = v.npc, npcID = v.npcID, zone = v.zone, coords = v.coords, faction = v.faction,
                  price = price, limited = (limitedSet and limitedSet[id]) and true or false, new = v.new }
  end
  return t
end

